import AppKit

// MARK: - Slider

/// A continuous value slider whose drag is a LIVE edit: `begin` on mouse
/// down, `write` on every move, `end` on mouse up (§4.3, the document's
/// `beginLiveEdit`/`updateLiveEdit`/`endLiveEdit` trio). Paired with an
/// `OptionFieldControl` in the same row, which commits typed values as a
/// single `applyEdit` instead.
///
/// It lives here rather than in `OptionControls.swift` because that file is
/// carried verbatim from Rasterize (app/CLAUDE.md: keep it in sync, do not
/// fork); it still conforms to `OptionControl` so `refreshOptionControls`
/// finds it like every other control.
final class InspectorSliderControl: NSView, OptionControl {
    private let lower: Double
    private let upper: Double
    private let read: () -> Double
    private let write: (Double) -> Void
    private let begin: () -> Void
    private let end: () -> Void
    private let enabled: () -> Bool
    /// The value at the selected action's START and at the PLAYHEAD
    /// (`InspectorBinding.startValue` / `nowValue`), nil when there is none.
    private let start: () -> Double?
    private let now: () -> Double?
    /// Whether the row is keyed — set by `inspectorValueRow` from the row's
    /// gutter once the row exists.
    var keyed: () -> Bool = { false }
    private var isActive = true
    private var dragging = false

    init(
        min lower: Double, max upper: Double, read: @escaping () -> Double,
        write: @escaping (Double) -> Void, begin: @escaping () -> Void,
        end: @escaping () -> Void, enabled: @escaping () -> Bool,
        start: @escaping () -> Double?, now: @escaping () -> Double?
    ) {
        self.start = start
        self.now = now
        self.lower = lower
        self.upper = Swift.max(upper, lower + 0.000_001)
        self.read = read
        self.write = write
        self.begin = begin
        self.end = end
        self.enabled = enabled
        super.init(frame: .zero)
        wantsLayer = true
        setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        setContentCompressionResistancePriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        translatesAutoresizingMaskIntoConstraints = false
        widthAnchor.constraint(greaterThanOrEqualToConstant: 60).isActive = true
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorSliderControl does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    override var intrinsicContentSize: NSSize {
        NSSize(width: NSView.noIntrinsicMetric, height: DS.controlHeight)
    }

    func refresh() {
        isActive = enabled()
        alphaValue = isActive ? 1 : 0.42
        needsDisplay = true
    }

    private var rail: InspectorRail { InspectorRail(lower: lower, upper: upper) }

    // MARK: Mouse

    override func mouseDown(with event: NSEvent) {
        guard isActive else { return }
        dragging = true
        begin()
        write(rail.value(atX: convert(event.locationInWindow, from: nil).x, width: bounds.width))
        needsDisplay = true
    }

    override func mouseDragged(with event: NSEvent) {
        guard dragging else { return }
        write(rail.value(atX: convert(event.locationInWindow, from: nil).x, width: bounds.width))
        needsDisplay = true
    }

    override func mouseUp(with event: NSEvent) {
        guard dragging else { return }
        dragging = false
        // Ends the gesture even when the value never moved: the document
        // registers no undo step for an unchanged handle, so this is free.
        end()
        needsDisplay = true
    }

    // MARK: Drawing

    override func draw(_ dirtyRect: NSRect) {
        rail.draw(
            in: self, value: read(), start: start(), now: now(), keyed: keyed(),
            keyedKnobInk: DS.textStrong.withAlphaComponent(1))
    }
}
import AppKit

/// One inspector row (spec §11 CI-9): the horizontal stack `inspectorRow`
/// always built — the mark gutter FIRST, with no spacing after it (CI-7) —
/// which now tracks the pointer over itself and answers a context menu.
///
/// The pointer is over the ROW, so the row tells its gutter (`hovered`); the
/// gutter decides whether that makes its ◆ a ×. The menu never reads the
/// hover: a window that is not key tracks none, and a right-click there must
/// offer the same items.
///
/// A field's or a popup's own right-click keeps its own menu, because neither
/// forwards it; the gutter, the label, a slider, a checkbox, the tags and the
/// trailing spacer reach this one.
final class InspectorRowView: NSStackView {
    let gutter: InspectorMarkGutter

    init(views: [NSView], gutter: InspectorMarkGutter) {
        self.gutter = gutter
        super.init(frame: .zero)
        for view in views { addArrangedSubview(view) }
        orientation = .horizontal
        alignment = .centerY
        spacing = 6
        setCustomSpacing(0, after: gutter)
        // As tall as the row and no taller: a fixed height would grow a row
        // of bare text (the "No filters" lines) and move everything under it.
        gutter.heightAnchor.constraint(equalTo: heightAnchor).isActive = true
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorRowView does not support NSCoder")
    }

    // MARK: Hover

    override func updateTrackingAreas() {
        super.updateTrackingAreas()
        // Only this view's own areas: a tooltip is a tracking area too.
        for area in trackingAreas where area.owner === self { removeTrackingArea(area) }
        addTrackingArea(
            NSTrackingArea(
                rect: .zero, options: [.mouseEnteredAndExited, .activeInKeyWindow, .inVisibleRect],
                owner: self, userInfo: nil))
    }

    override func mouseEntered(with event: NSEvent) { setHovered(true) }
    override func mouseExited(with event: NSEvent) { setHovered(false) }

    func setHovered(_ hovered: Bool) {
        gutter.hovered = hovered
    }

    // MARK: The menu

    override func menu(for event: NSEvent) -> NSMenu? {
        contextMenu()
    }

    /// The row's items, in order: "Remove from action N" on a keyed row, "Go
    /// to action M" on a ◇ row, then — for a row with a default — "Set end
    /// value to default" with an action selected on a row that animates, else
    /// "Reset to default", disabled while the row already holds it. Nil when
    /// there would be no item.
    func contextMenu() -> NSMenu? {
        let menu = NSMenu()
        menu.autoenablesItems = false
        let binding = gutter.binding
        if gutter.isKeyed, let number = binding?.selectedActionNumber {
            add("Remove from action \(number)", #selector(removeFromAction(_:)), to: menu)
        }
        if case .other(let number) = gutter.mark {
            add("Go to action \(number)", #selector(goToAction(_:)), to: menu)
        }
        if let rowDefault = gutter.default {
            let atEnd = binding?.selectedAction != nil && gutter.animates
            let item = add(
                atEnd ? "Set end value to default" : "Reset to default",
                #selector(resetToDefault(_:)), to: menu)
            item.isEnabled = rowDefault.differs()
        }
        return menu.items.isEmpty ? nil : menu
    }

    @discardableResult
    private func add(_ title: String, _ action: Selector, to menu: NSMenu) -> NSMenuItem {
        let item = NSMenuItem(title: title, action: action, keyEquivalent: "")
        item.target = self
        menu.addItem(item)
        return item
    }

    @objc func removeFromAction(_ sender: Any?) {
        gutter.removeFromAction()
    }

    /// Selects the action the ◇ names, through the lane's own intent.
    @objc func goToAction(_ sender: Any?) {
        guard case .other(let number) = gutter.mark, let binding = gutter.binding,
              let id = binding.actionID(number: number)
        else { return }
        binding.selectAction(id)
    }

    @objc func resetToDefault(_ sender: Any?) {
        guard let rowDefault = gutter.default, let binding = gutter.binding else { return }
        binding.apply(rowDefault.name, rowDefault.ops())
    }
}

import AppKit

// MARK: - OptionControl

/// Shared surface of the options-bar controls: a fixed intrinsic size, and a
/// `refresh()` that re-reads the descriptor closures (value and enabled
/// state). A disabled control dims to 42% and ignores input; the closures
/// stay the single source of truth — no control stores a value.
protocol OptionControl: NSView {
    func refresh()
}

// MARK: - OptionFieldControl

/// A borderless NSTextField gives no focus callback; this one reports
/// becoming first responder so its owner can swap the formatted rest
/// display ("24 px") for the bare editable number.
private final class FocusReportingTextField: NSTextField {
    var onFocus: (() -> Void)?

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("FocusReportingTextField does not support NSCoder")
    }

    override func becomeFirstResponder() -> Bool {
        let accepted = super.becomeFirstResponder()
        if accepted { onFocus?() }
        return accepted
    }
}

/// Numeric option field: a bordered container around an embedded borderless
/// mono field. At rest it shows the formatted value plus unit; while editing
/// it shows the bare number. Enter and end-editing commit (clamped to the
/// descriptor's range), Escape reverts. A non-empty `quick` list appends a
/// chevron zone on the right that pops a menu of those preset values.
final class OptionFieldControl: NSView, NSTextFieldDelegate, OptionControl {
    private let fixedWidth: CGFloat
    private let unit: String
    private let decimals: Int
    private let lower: Double
    private let upper: Double
    private let quick: [Double]
    private let read: () -> Double
    private let write: (Double) -> Void
    private let enabled: () -> Bool
    private let onEdit: () -> Void
    private let field = FocusReportingTextField(frame: .zero)
    private var isActive = true
    /// True while an Enter/Escape hand-off is resigning first responder, so
    /// the resulting end-editing notification doesn't commit a second time.
    private var finishing = false

    /// Width the quick-pick chevron zone adds beyond the text width.
    private static let quickZoneWidth: CGFloat = 15

    init(
        width: CGFloat, unit: String, decimals: Int, min: Double, max: Double,
        quick: [Double] = [],
        read: @escaping () -> Double, write: @escaping (Double) -> Void,
        enabled: @escaping () -> Bool, onEdit: @escaping () -> Void
    ) {
        self.fixedWidth = width
        self.unit = unit
        self.decimals = decimals
        self.lower = min
        self.upper = max
        self.quick = quick
        self.read = read
        self.write = write
        self.enabled = enabled
        self.onEdit = onEdit
        super.init(frame: .zero)
        wantsLayer = true
        field.isBezeled = false
        field.isBordered = false
        field.drawsBackground = false
        field.focusRingType = .none
        field.font = DS.mono(11)
        field.textColor = DS.textStrong
        field.usesSingleLineMode = true
        field.lineBreakMode = .byClipping
        field.delegate = self
        field.onFocus = { [weak self] in self?.beginBareEditing() }
        addSubview(field)
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("OptionFieldControl does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    private var quickZone: CGFloat {
        quick.isEmpty ? 0 : Self.quickZoneWidth
    }

    override var intrinsicContentSize: NSSize {
        NSSize(width: fixedWidth + quickZone, height: DS.controlHeight)
    }

    override func layout() {
        super.layout()
        let height = ceil(DS.mono(11).boundingRectForFont.height)
        field.frame = NSRect(
            x: 7, y: floor((bounds.height - height) / 2),
            width: max(0, bounds.width - 14 - quickZone), height: height)
    }

    override func draw(_ dirtyRect: NSRect) {
        let path = NSBezierPath(
            roundedRect: bounds.insetBy(dx: 0.5, dy: 0.5),
            xRadius: DS.controlRadius, yRadius: DS.controlRadius)
        NSColor.controlBackgroundColor.setFill()
        path.fill()
        DS.border.setStroke()
        path.stroke()

        guard !quick.isEmpty else { return }
        if let icon = NSImage(
            systemSymbolName: "chevron.down", accessibilityDescription: "Quick values")?
            .withSymbolConfiguration(NSImage.SymbolConfiguration(pointSize: 8, weight: .semibold))
        {
            let tinted = icon.tinted(with: DS.textMuted)
            let size = tinted.size
            tinted.draw(
                in: NSRect(
                    x: bounds.width - 5 - size.width, y: (bounds.height - size.height) / 2,
                    width: size.width, height: size.height))
        } else {
            let attributes: [NSAttributedString.Key: Any] = [
                .font: DS.sans(9), .foregroundColor: DS.textMuted,
            ]
            let size = "▾".size(withAttributes: attributes)
            "▾".draw(
                at: NSPoint(
                    x: bounds.width - 5 - size.width, y: (bounds.height - size.height) / 2),
                withAttributes: attributes)
        }
    }

    override func mouseDown(with event: NSEvent) {
        // The 7pt margins around the embedded field still read as the
        // control; a click anywhere on it starts editing — except the
        // quick-pick chevron zone, which pops the preset menu.
        guard isActive else { return }
        let point = convert(event.locationInWindow, from: nil)
        if !quick.isEmpty, point.x >= bounds.width - Self.quickZoneWidth {
            showQuickMenu()
            return
        }
        window?.makeFirstResponder(field)
    }

    /// The chevron's preset menu: each value formatted exactly as the field
    /// shows it at rest, checkmarked on the current value.
    private func showQuickMenu() {
        if field.currentEditor() != nil { finishEditing(commit: true) }
        let menu = NSMenu()
        let current = read()
        for (index, value) in quick.enumerated() {
            let item = NSMenuItem(
                title: String(format: "%.\(decimals)f", value) + unit,
                action: #selector(quickPicked(_:)), keyEquivalent: "")
            item.target = self
            item.tag = index
            item.state = abs(value - current) < 0.0001 ? .on : .off
            menu.addItem(item)
        }
        menu.minimumWidth = bounds.width
        menu.popUp(positioning: nil, at: NSPoint(x: 0, y: bounds.height + 2), in: self)
    }

    @objc private func quickPicked(_ sender: NSMenuItem) {
        guard quick.indices.contains(sender.tag) else { return }
        let value = Swift.min(upper, Swift.max(lower, quick[sender.tag]))
        // Same unchanged-value guard as typed commits: setters that do real
        // work (the selection-morphology fields) must not re-fire on a
        // pick of the value already showing.
        guard abs(value - read()) > 0.0001 else { return }
        write(value)
        onEdit()
        field.stringValue = restText()
    }

    func refresh() {
        isActive = enabled()
        alphaValue = isActive ? 1 : 0.42
        field.isEditable = isActive
        field.isSelectable = isActive
        guard field.currentEditor() == nil else { return }
        field.stringValue = restText()
    }

    // MARK: Editing

    private func restText() -> String {
        bareText() + unit
    }

    private func bareText() -> String {
        String(format: "%.\(decimals)f", read())
    }

    private func beginBareEditing() {
        field.stringValue = bareText()
        if let editor = field.currentEditor() as? NSTextView {
            editor.drawsBackground = false
        }
        field.currentEditor()?.selectAll(nil)
    }

    private func parsedValue(_ text: String) -> Double? {
        var trimmed = text.trimmingCharacters(in: .whitespaces)
        let bareUnit = unit.trimmingCharacters(in: .whitespaces)
        if !bareUnit.isEmpty, trimmed.hasSuffix(bareUnit) {
            trimmed = String(trimmed.dropLast(bareUnit.count))
                .trimmingCharacters(in: .whitespaces)
        }
        return Double(trimmed)
    }

    private func commitCurrentText() {
        guard let value = parsedValue(field.stringValue) else { return }
        let clamped = Swift.min(upper, Swift.max(lower, value))
        // An unchanged value is not an edit: some setters do real work on
        // write (the selection-morphology fields apply their op), so merely
        // focusing a field and tabbing away must not fire them.
        guard abs(clamped - read()) > 0.0001 else { return }
        write(clamped)
        onEdit()
    }

    private func finishEditing(commit: Bool) {
        finishing = true
        if commit { commitCurrentText() }
        window?.makeFirstResponder(window?.contentView)  // #60
        finishing = false
        field.stringValue = restText()
    }

    func control(
        _ control: NSControl, textView: NSTextView, doCommandBy commandSelector: Selector
    ) -> Bool {
        if commandSelector == #selector(NSResponder.insertNewline(_:)) {
            finishEditing(commit: true)
            return true
        }
        if commandSelector == #selector(NSResponder.cancelOperation(_:)) {
            finishEditing(commit: false)
            return true
        }
        return false
    }

    func controlTextDidEndEditing(_ obj: Notification) {
        // Click-away and Tab land here directly; Enter/Escape came through
        // finishEditing and already handled the commit.
        guard !finishing else { return }
        commitCurrentText()
        field.stringValue = restText()
    }
}

