/// The Text tab's content editor: an `NSTextView` that commits on blur,
/// because a text clip's content is typed, not dialled. Its keys are the
/// canvas editor's (spec §11 K-2, K-4): a bare Return or keypad Enter
/// applies and hands the keys back to the editor, Return with ⇧, ⌘, ⌥ or ⌃
/// is a new line, and the editor window takes Tab (with Full Keyboard Access
/// off) and a click outside. The
/// `refresh()` is skipped while it holds first responder, or every keystroke
/// would be overwritten by the value it just wrote.
final class InspectorTextArea: NSView, OptionControl, NSTextViewDelegate {
    private let read: () -> String
    private let write: (String) -> Void
    private let enabled: () -> Bool
    private let onEdit: () -> Void
    private let textView = InspectorTextAreaView()
    private let scroll = NSScrollView()

    init(
        read: @escaping () -> String, write: @escaping (String) -> Void,
        enabled: @escaping () -> Bool, onEdit: @escaping () -> Void
    ) {
        self.read = read
        self.write = write
        self.enabled = enabled
        self.onEdit = onEdit
        super.init(frame: .zero)
        wantsLayer = true
        setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        textView.isRichText = false
        textView.font = DS.sans(12)
        textView.textColor = DS.textStrong
        textView.drawsBackground = true
        textView.backgroundColor = .textBackgroundColor
        textView.isVerticallyResizable = true
        textView.isHorizontallyResizable = false
        textView.autoresizingMask = [.width]
        textView.textContainerInset = NSSize(width: 4, height: 4)
        textView.delegate = self
        scroll.documentView = textView
        scroll.hasVerticalScroller = true
        scroll.drawsBackground = false
        scroll.borderType = .noBorder
        scroll.wantsLayer = true
        scroll.layer?.cornerRadius = DS.controlRadius
        scroll.layer?.borderWidth = 1
        scroll.layer?.borderColor = DS.border.cgColor
        scroll.translatesAutoresizingMaskIntoConstraints = false
        addSubview(scroll)
        NSLayoutConstraint.activate([
            scroll.topAnchor.constraint(equalTo: topAnchor),
            scroll.bottomAnchor.constraint(equalTo: bottomAnchor),
            scroll.leadingAnchor.constraint(equalTo: leadingAnchor),
            scroll.trailingAnchor.constraint(equalTo: trailingAnchor),
            scroll.heightAnchor.constraint(equalToConstant: 72),
        ])
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorTextArea does not support NSCoder")
    }

    func refresh() {
        let active = enabled()
        alphaValue = active ? 1 : 0.42
        textView.isEditable = active
        textView.isSelectable = active
        guard window?.firstResponder !== textView else { return }
        let value = read()
        if textView.string != value { textView.string = value }
    }

    private func commit() {
        let value = textView.string
        guard value != read() else { return }
        write(value)
        onEdit()
    }

    func textDidEndEditing(_ notification: Notification) {
        commit()
    }
}

/// `InspectorTextArea`'s text view: Return through `TextEditKey.route`, as
/// `CanvasTextView` and the composer route it. Applying is leaving — first
/// responder to the window's content view, whose resign runs the area's
/// `textDidEndEditing` commit — so there is one commit path, the blur's.
private final class InspectorTextAreaView: NSTextView {
    override func keyDown(with event: NSEvent) {
        switch TextEditKey.route(event, hasMarkedText: hasMarkedText()) {
        case .apply: window?.makeFirstResponder(window?.contentView)
        case .newline: insertNewline(nil)
        case .escape, nil: super.keyDown(with: event)
        }
    }
}
import AppKit

/// An editable one-line string — a marker's name, a graphic's string
/// property, a clip's own name. `OptionFieldControl` is numeric only, and a
/// name is the one text value the inspector edits outside the Text tab's
/// content area.
///
/// It LOOKS like the inspector's value field (spec §11 SH-3): filled, a 1 pt
/// `DS.border` stroke, 7 pt padding, the line centred vertically — drawn by
/// `InspectorNameFieldCell`, not a layer border, so it follows the appearance
/// and a `cacheDisplay` capture holds it. It pins its own height at
/// `DS.controlHeight`, one constraint, which the clip header re-pins. Its
/// alignment rect is its frame (no insets), so a constraint places the box
/// where it places a value field's, and the text and the field editor move
/// with it (kpgalligan/framejob#186).
///
/// Its placeholder is kept off the cell, in a string of its own: the cell
/// draws it, at rest and under an empty field editor, on the resting rows,
/// and the field editor — which draws a cell's placeholder 2 pt lower — is
/// given none. Every text change redisplays the field, so the placeholder
/// goes with the first letter typed and comes back with the last deleted
/// (kpgalligan/framejob#199).
final class InspectorNameField: NSTextField, OptionControl, NSTextFieldDelegate {
    private let read: () -> String
    private let write: (String) -> Void
    /// Not `enabled`: `NSControl` already owns that name, and a stored
    /// property would be read as an override of it.
    private let isLive: () -> Bool
    private let onEdit: () -> Void
    private var placeholder: String?

    override class var cellClass: AnyClass? {
        get { InspectorNameFieldCell.self }
        set {}
    }

    override var alignmentRectInsets: NSEdgeInsets { NSEdgeInsets() }

    override var placeholderString: String? {
        get { placeholder }
        set {
            placeholder = newValue
            setAccessibilityPlaceholderValue(newValue)
            needsDisplay = true
        }
    }

    override var placeholderAttributedString: NSAttributedString? {
        get { placeholderString.map { NSAttributedString(string: $0) } }
        set { placeholderString = newValue?.string }
    }

    override func textDidChange(_ notification: Notification) {
        super.textDidChange(notification)
        needsDisplay = true
    }

    init(
        read: @escaping () -> String, write: @escaping (String) -> Void,
        enabled: @escaping () -> Bool, onEdit: @escaping () -> Void
    ) {
        self.read = read
        self.write = write
        self.isLive = enabled
        self.onEdit = onEdit
        super.init(frame: .zero)
        isBezeled = false
        isBordered = false
        drawsBackground = false
        focusRingType = .none
        textColor = DS.textStrong
        font = DS.sans(11)
        usesSingleLineMode = true
        cell?.isScrollable = true
        lineBreakMode = .byTruncatingTail
        heightAnchor.constraint(equalToConstant: DS.controlHeight).isActive = true
        delegate = self
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorNameField does not support NSCoder")
    }

    func refresh() {
        let active = isLive()
        alphaValue = active ? 1 : 0.42
        isEditable = active
        isSelectable = active
        // Skipped while the field is being typed into, or the value it is
        // about to commit would be overwritten by the one it replaces.
        guard currentEditor() == nil else { return }
        let value = read()
        if stringValue != value { stringValue = value }
    }

    func controlTextDidEndEditing(_ obj: Notification) {
        let value = stringValue
        if value != read() {
            write(value)
            onEdit()
        }
        // Re-read directly rather than through `refresh()`: every refresh the
        // commit just ran was skipped, because the field editor is still
        // attached here, so the field would go on showing what was typed
        // (blank after a clear, padded text after a padded rename, blank on a
        // clip whose empty commit sent nothing) while the model holds the
        // trimmed name or the fallback. The timecode field's beep path sets
        // itself the same way.
        let now = read()
        if stringValue != now { stringValue = now }
    }
}

/// `InspectorNameField`'s cell: `OptionFieldControl`'s box — the
/// `controlBackgroundColor` fill and the 1 pt `DS.border` stroke on the
/// bounds inset by half a point — with the text inset by `padding` on each
/// side and its line box centred vertically, at rest and while the field
/// editor is attached (spec §11 SH-3).
final class InspectorNameFieldCell: NSTextFieldCell {
    static let padding: CGFloat = 7
    /// The field editor's own `lineFragmentPadding`, which the rest drawing
    /// matches.
    private static let lineFragmentPadding: CGFloat = 2

    override init(textCell string: String) {
        super.init(textCell: string)
    }

    @available(*, unavailable)
    required init(coder: NSCoder) {
        fatalError("InspectorNameFieldCell does not support NSCoder")
    }

    /// `rect` less the padding, cut to one line box and centred in it.
    private func lineRect(in rect: NSRect) -> NSRect {
        let inset = rect.insetBy(dx: Self.padding, dy: 0)
        let face = font ?? DS.sans(11)
        let line = min(inset.height, ceil(face.ascender - face.descender + face.leading))
        return NSRect(
            x: inset.minX, y: inset.minY + floor((inset.height - line) / 2),
            width: max(0, inset.width), height: line)
    }

    override func titleRect(forBounds rect: NSRect) -> NSRect {
        lineRect(in: rect)
    }

    override func drawingRect(forBounds rect: NSRect) -> NSRect {
        lineRect(in: rect)
    }

    /// Super's, widened by the padding on both sides, so the field's
    /// intrinsic width — and the layout dump's truncation rule — counts it.
    override func cellSize(forBounds rect: NSRect) -> NSSize {
        let size = super.cellSize(forBounds: rect)
        return NSSize(width: size.width + 2 * Self.padding, height: size.height)
    }

    override func draw(withFrame cellFrame: NSRect, in controlView: NSView) {
        let path = NSBezierPath(
            roundedRect: cellFrame.insetBy(dx: 0.5, dy: 0.5),
            xRadius: DS.controlRadius, yRadius: DS.controlRadius)
        NSColor.controlBackgroundColor.setFill()
        path.fill()
        DS.border.setStroke()
        path.stroke()
        drawInterior(withFrame: cellFrame, in: controlView)
    }

    /// The text at rest, drawn by the text system the field editor lays
    /// out with — its line fragment padding and baseline, in the same line
    /// rect — so clicking in moves no glyph. Super's own rest drawing sits
    /// 1–2 pt below the field editor's line in this rect (measured: 2 pt at
    /// 11 pt, 1 pt at 12 pt). The placeholder is the FIELD's
    /// (`InspectorNameField.placeholderString`, never the cell's), drawn here
    /// at rest when the value is empty and, with the field editor attached,
    /// when the editor's string is empty — on the same rows either way, and
    /// once, since the field editor has none to draw. With the field editor
    /// attached and holding text nothing is drawn: it draws the text itself.
    override func drawInterior(withFrame cellFrame: NSRect, in controlView: NSView) {
        let editor = (controlView as? NSTextField)?.currentEditor()
        let shown = editor.map { $0.string } ?? stringValue
        let placeholder = (controlView as? InspectorNameField)?.placeholderString ?? ""
        let face = font ?? DS.sans(11)
        let text: NSMutableAttributedString
        if !shown.isEmpty {
            if editor != nil { return }
            text = NSMutableAttributedString(attributedString: attributedStringValue)
        } else if !placeholder.isEmpty {
            text = NSMutableAttributedString(
                string: placeholder,
                attributes: [.font: face, .foregroundColor: NSColor.placeholderTextColor])
        } else {
            return
        }
        let paragraph = NSMutableParagraphStyle()
        paragraph.alignment = alignment
        paragraph.lineBreakMode = .byTruncatingTail
        text.addAttribute(
            .paragraphStyle, value: paragraph, range: NSRange(location: 0, length: text.length))
        text.draw(
            with: lineRect(in: cellFrame).insetBy(dx: Self.lineFragmentPadding, dy: 0),
            options: [.usesLineFragmentOrigin, .truncatesLastVisibleLine])
    }

    override func edit(
        withFrame rect: NSRect, in controlView: NSView, editor textObj: NSText, delegate: Any?,
        event: NSEvent?
    ) {
        super.edit(
            withFrame: lineRect(in: rect), in: controlView, editor: textObj, delegate: delegate,
            event: event)
    }

    override func select(
        withFrame rect: NSRect, in controlView: NSView, editor textObj: NSText, delegate: Any?,
        start selStart: Int, length selLength: Int
    ) {
        super.select(
            withFrame: lineRect(in: rect), in: controlView, editor: textObj, delegate: delegate,
            start: selStart, length: selLength)
    }
}

import AppKit

// MARK: - Sections

/// One disclosure group: a header with the title, a right-aligned summary of
/// what the group currently says, an optional reset-to-default button, and the
/// rows. Collapsed state is per section id in `UserDefaults`, so a pane
/// rebuilt after every edit does not keep re-opening a group the user closed.
///
/// **The stored value records COLLAPSED, not expanded** — a section nobody has
/// touched has no stored value at all, which is what lets `defaultExpanded`
/// mean anything. Flipping that spelling would invert every saved panel.
final class InspectorSection: NSView {
    /// `UserDefaults` key prefix; the suffix is the section's stable id.
    static let collapsedKeyPrefix = "FrameJobInspectorSection."

    let id: String
    let title: String
    let header = InspectorSectionHeader()
    private let content = NSStackView()
    private(set) var isExpanded = true
    private let summary: (() -> String?)?
    /// An explicit "differs from its default" (spec §11 CI-9), for a section
    /// whose rows do not read the props or whose Reset writes fewer keys
    /// than its rows read; nil folds the rows' own defaults.
    private let differs: (() -> Bool)?
    /// The rows' marks, folded (road map 9 §5) at the end of `init` and on
    /// every `refresh()`.
    private(set) var marks = SectionMarks.empty
    /// "Actions don't animate this" — shown while every row that writes is ⊘.
    private var inertNote: InspectorNoteLabel?
    /// The header's click, after the preference is stored — and nothing else:
    /// `reveal()` and `expandByDefault()` never call it (`KeyedReveal`).
    var didToggle: ((InspectorSection) -> Void)?

    /// `summary` is a closure rather than a string because it is re-read on
    /// every `refresh()`: a collapsed section still has to tell the truth
    /// about the value under it. `defaultExpanded` is the state before the
    /// user has ever touched THIS section — the design opens Transform and
    /// the primary section of a text or shape selection, and closes the rest.
    init(
        id: String, title: String, summary: (() -> String?)? = nil,
        note: (() -> String?)? = nil, reset: (() -> Void)? = nil,
        differs: (() -> Bool)? = nil, defaultExpanded: Bool = true, rows: [NSView]
    ) {
        self.id = id
        self.title = title
        self.summary = summary
        self.differs = differs
        super.init(frame: .zero)
        let key = Self.collapsedKeyPrefix + id
        if let collapsed = UserDefaults.standard.object(forKey: key) as? Bool {
            isExpanded = !collapsed
        } else {
            isExpanded = defaultExpanded
        }

        content.orientation = .vertical
        content.alignment = .leading
        content.spacing = InspectorMetrics.rowSpacing
        content.edgeInsets = NSEdgeInsets(
            top: 2, left: InspectorMetrics.inset, bottom: 8, right: InspectorMetrics.inset)
        let inert = InspectorNoteLabel { [weak self] in
            self?.marks.allNotAnimatable == true
                ? "Actions don't animate this. Edits here change the clip." : nil
        }
        inert.textColor = DS.textFaint
        inertNote = inert
        addRow(inert)
        if let note = note {
            addRow(InspectorNoteLabel(note: note))
        }
        for row in rows { addRow(row) }

        header.configure(title: title, reset: reset, clear: { [weak self] in self?.clear() })
        header.onToggle = { [weak self] in self?.toggle() }

        let stack = NSStackView(views: [header, content])
        stack.orientation = .vertical
        stack.alignment = .leading
        stack.spacing = 0
        stack.translatesAutoresizingMaskIntoConstraints = false
        addSubview(stack)
        NSLayoutConstraint.activate([
            stack.topAnchor.constraint(equalTo: topAnchor),
            stack.bottomAnchor.constraint(equalTo: bottomAnchor),
            stack.leadingAnchor.constraint(equalTo: leadingAnchor),
            stack.trailingAnchor.constraint(equalTo: trailingAnchor),
            header.widthAnchor.constraint(equalTo: stack.widthAnchor),
            content.widthAnchor.constraint(equalTo: stack.widthAnchor),
        ])
        content.isHidden = !isExpanded
        header.isExpanded = isExpanded
        for gutter in Self.gutters(in: content) { gutter.refresh() }
        foldMarks()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorSection does not support NSCoder")
    }

    private func addRow(_ row: NSView) {
        content.addArrangedSubview(row)
        row.widthAnchor.constraint(
            equalTo: content.widthAnchor, constant: -2 * InspectorMetrics.inset).isActive = true
    }

    private func toggle() {
        isExpanded.toggle()
        // The redesign's one animation (spec §11 CI-15): through `DS.animate`,
        // which runs it unanimated under Reduce Motion. The state is set at once.
        DS.animate(DS.stateDuration) {
            content.isHidden = !isExpanded
            superview?.layoutSubtreeIfNeeded()
        }
        header.isExpanded = isExpanded
        UserDefaults.standard.set(!isExpanded, forKey: Self.collapsedKeyPrefix + id)
        didToggle?(self)
    }

    /// Opens the section and writes NO preference — the selected action's
    /// auto-open (spec §11 CI-8), which must leave the person's own layout
    /// standing for when the action is left.
    func reveal() {
        isExpanded = true
        content.isHidden = false
        header.isExpanded = true
    }

    /// Opens the section as a DEFAULT, for a pane that decided after building
    /// it that this is the group to open (`ClipPane`'s "the first section is
    /// open when there is no Transform"). `defaultExpanded` cannot say it: the
    /// pane only knows which section is first once it has them all.
    ///
    /// **It defers to the user and writes nothing.** A section the user has
    /// ever toggled has a stored value, and re-opening a group somebody closed
    /// on every rebuild would be worse than the closed panel this fixes;
    /// storing the state here would then make that override permanent.
    /// Returns whether it opened the section, so a caller walking a list can
    /// stop at the first one that had no stored preference.
    @discardableResult
    func expandByDefault() -> Bool {
        guard UserDefaults.standard.object(forKey: Self.collapsedKeyPrefix + id) == nil,
              !isExpanded
        else { return false }
        isExpanded = true
        content.isHidden = false
        header.isExpanded = true
        return true
    }

    func refresh() {
        refreshOptionControls(in: content)
        foldMarks()
    }

    /// The header's Clear (spec §11 CI-9): every key the section's rows
    /// write that the selected action holds, out of its end patch in ONE
    /// `set_action_end`.
    func clear() {
        let gutters = Self.gutters(in: content)
        guard let binding = gutters.lazy.compactMap({ $0.binding }).first else { return }
        let keys = gutters.reduce(into: Set<String>()) { $0.formUnion($1.keyedWrites()) }
        binding.apply("Clear", binding.clearOps(keys))
    }

    /// The rows' gutters, in the order `refreshOptionControls(in:)` walks.
    private static func gutters(in view: NSView) -> [InspectorMarkGutter] {
        view.subviews.flatMap { subview -> [InspectorMarkGutter] in
            if let gutter = subview as? InspectorMarkGutter { return [gutter] }
            return gutters(in: subview)
        }
    }

    /// `marks` from the gutters as they stand, then the two things drawn from
    /// it: the ⊘ note and the header. A section is EDITING the selected
    /// action when any of its rows animates; one that none does (Document,
    /// Shape, a ⊘-only section) keeps its Reset, since its edits go to the
    /// clip.
    private func foldMarks() {
        let gutters = Self.gutters(in: content)
        let writing = gutters.filter { !$0.writes.isEmpty }
        let binding = gutters.lazy.compactMap { $0.binding }.first
        marks = SectionMarks(
            keyed: gutters.reduce(into: Set<String>()) { $0.formUnion($1.keyedWrites()) }.count,
            other: gutters.contains {
                if case .other = $0.mark { return true } else { return false }
            },
            allNotAnimatable: !writing.isEmpty
                && writing.allSatisfy { $0.mark == .notAnimatable },
            differs: differs?() ?? gutters.contains { $0.default?.differs() == true },
            editing: gutters.contains { $0.animates } ? binding?.selectedActionNumber : nil)
        inertNote?.refresh()
        header.refresh(summary: summary?(), marks: marks)
    }
}

/// The auto-open (spec §11 CI-8): the sections the selected action keys are
/// revealed on the sub-tab showing them, remembered for as long as that
/// action stays selected — so a rebuild under the same action re-reveals
/// them, a sub-tab first shown later adds its own, and a header click that
/// closes one drops it. One per `ClipPane`, applied at the end of every
/// `makeSections()`; it lives here because `ClipPane.swift` is at its cap.
final class KeyedReveal {
    private(set) var action: UInt32?
    private(set) var seen: Set<String> = []
    private(set) var ids: Set<String> = []

    func apply(_ sections: [InspectorSection], action: UInt32?, subTab: String) {
        guard let action else {
            (self.action, seen, ids) = (nil, [], [])
            return
        }
        if action != self.action { (self.action, seen, ids) = (action, [], []) }
        if !seen.contains(subTab) {
            seen.insert(subTab)
            ids.formUnion(sections.filter { $0.marks.keyed > 0 }.map(\.id))
        }
        for section in sections {
            section.didToggle = { [weak self] in self?.ids.remove($0.id) }
            if ids.contains(section.id) { section.reveal() }
        }
    }
}
import AppKit

/// The section header: disclosure triangle, title in the micro-label face, the
/// current-state summary, and the Reset or Clear button pinned to the trailing
/// edge. The buttons are subviews so they eat their own clicks — everything
/// else toggles the group.
///
/// Spec §11 CI-9: a section EDITING an action (`marks.editing`) shows Clear,
/// only while the action keys one of its rows; otherwise it shows Reset, only
/// while it differs from its default. Both share the one slot, and at most
/// one is visible.
final class InspectorSectionHeader: NSView {
    var onToggle: (() -> Void)?
    var isExpanded = true {
        didSet { needsDisplay = true }
    }
    private var title = ""
    /// The last summary and marks drawn, so a refresh only redraws when one
    /// CHANGED — the panel refreshes on every document change and on every
    /// playhead move inside an action.
    private var lastSummary: String?
    private var marks = SectionMarks.empty
    /// Held so the summary can stop short of the VISIBLE one: they share the
    /// header's trailing end, and a summary drawn under a button would be
    /// unreadable. Clear is always built; Reset only for a section with one.
    private weak var resetButton: NSView?
    private weak var clearButton: NSView?
    /// The hover (#102, spec §11 CI-15 as amended): a second `DS.hoverFill`
    /// over the rest band, faded by its alpha, since a band drawn in
    /// `draw(_:)` cannot fade. The first subview, so Reset and Clear sit
    /// above it; it stops above the rule.
    let hoverBand = InspectorHeaderHoverBand()
    private(set) var isHovered = false

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
        wantsLayer = true
        hoverBand.translatesAutoresizingMaskIntoConstraints = false
        addSubview(hoverBand)
        NSLayoutConstraint.activate([
            hoverBand.leadingAnchor.constraint(equalTo: leadingAnchor),
            hoverBand.trailingAnchor.constraint(equalTo: trailingAnchor),
            hoverBand.topAnchor.constraint(equalTo: topAnchor),
            hoverBand.bottomAnchor.constraint(equalTo: bottomAnchor, constant: -1),
        ])
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorSectionHeader does not support NSCoder")
    }

    convenience init() {
        self.init(frame: .zero)
    }

    override var isFlipped: Bool { true }

    override var intrinsicContentSize: NSSize {
        NSSize(width: NSView.noIntrinsicMetric, height: InspectorMetrics.headerHeight)
    }

    func configure(title: String, reset: (() -> Void)?, clear: @escaping () -> Void) {
        self.title = title
        clearButton = install(
            OptionButtonControl(title: "Clear", action: clear, enabled: { true }, onEdit: {}))
        if let reset {
            let button = install(
                OptionButtonControl(title: "Reset", action: reset, enabled: { true }, onEdit: {}))
            button.toolTip = "Reset this section to its defaults"
            resetButton = button
        }
        showButtons()
    }

    private func install(_ button: NSView) -> NSView {
        button.translatesAutoresizingMaskIntoConstraints = false
        addSubview(button)
        NSLayoutConstraint.activate([
            button.trailingAnchor.constraint(
                equalTo: trailingAnchor, constant: -InspectorMetrics.inset),
            button.centerYAnchor.constraint(equalTo: centerYAnchor),
        ])
        return button
    }

    /// CI-9's one slot: Clear while editing an action that keys the section,
    /// Reset while not editing and the section differs, else nothing.
    private func showButtons() {
        let editing = marks.editing
        clearButton?.isHidden = editing == nil || marks.keyed == 0
        clearButton?.toolTip = editing.map { "Remove this section from action \($0)" }
        resetButton?.isHidden = editing != nil || !marks.differs
    }

    /// The visible button's title — "Clear", "Reset" or nil.
    var buttonTitle: String? {
        if clearButton?.isHidden == false { return "Clear" }
        if resetButton?.isHidden == false { return "Reset" }
        return nil
    }

    /// The summary's ink: the action's when keyed, the body tier
    /// (`DS.textMuted`, spec §11 CI-9) when the section differs from its
    /// default, else faint.
    var summaryInk: NSColor {
        marks.keyed > 0 ? DS.action : marks.differs ? DS.textMuted : DS.textFaint
    }

    /// Takes the summary and the marks; redraws only when either moved.
    func refresh(summary: String?, marks: SectionMarks) {
        guard summary != lastSummary || marks != self.marks else { return }
        lastSummary = summary
        self.marks = marks
        showButtons()
        needsDisplay = true
    }

    override func mouseDown(with event: NSEvent) {
        onToggle?()
    }

    override func updateTrackingAreas() {
        super.updateTrackingAreas()
        // Owner-filtered: a tooltip is a tracking area too (app/CLAUDE.md).
        for area in trackingAreas where area.owner === self { removeTrackingArea(area) }
        addTrackingArea(
            NSTrackingArea(
                rect: bounds, options: [.mouseEnteredAndExited, .activeInKeyWindow],
                owner: self, userInfo: nil))
    }

    override func mouseEntered(with event: NSEvent) {
        setHovered(true)
    }

    override func mouseExited(with event: NSEvent) {
        setHovered(false)
    }

    /// The state at once, the band's alpha through `DS.animate` — set
    /// directly inside it, never through `animator()`, which animates even
    /// outside a group and so would ignore Reduce Motion.
    private func setHovered(_ hovered: Bool) {
        guard hovered != isHovered else { return }
        isHovered = hovered
        DS.animate(DS.hoverDuration) {
            hoverBand.alphaValue = hovered ? 1 : 0
        }
    }

    override func draw(_ dirtyRect: NSRect) {
        // **Pitfall:** `DS.hoverFill` is `quaternaryLabelColor`, which is
        // ALREADY about 10% ink — taking 0.35 of it left a 3.5% wash that is
        // invisible in the light appearance, so the header did not separate
        // from the rows under it. Drawn at its own alpha it is a quiet band
        // that reads in both appearances.
        DS.hoverFill.setFill()
        bounds.fill()
        DS.border.setFill()
        NSRect(x: 0, y: bounds.height - 1, width: bounds.width, height: 1).fill()

        let glyph = isExpanded ? "chevron.down" : "chevron.right"
        let box = NSRect(x: InspectorMetrics.inset, y: bounds.midY - 5, width: 10, height: 10)
        if let icon = NSImage(systemSymbolName: glyph, accessibilityDescription: title)?
            .withSymbolConfiguration(NSImage.SymbolConfiguration(pointSize: 9, weight: .semibold))
        {
            let tinted = icon.tinted(with: DS.textMuted)
            let size = tinted.size
            tinted.draw(
                in: NSRect(
                    x: box.minX, y: box.midY - size.height / 2, width: size.width,
                    height: size.height))
        } else {
            let attributes: [NSAttributedString.Key: Any] = [
                .font: DS.sans(9), .foregroundColor: DS.textMuted,
            ]
            (isExpanded ? "▾" : "▸").draw(
                at: NSPoint(x: box.minX, y: box.minY), withAttributes: attributes)
        }

        let label = Self.titleLabel(title)
        label.draw(at: NSPoint(x: box.maxX + 6, y: bounds.midY - label.size().height / 2))
        drawSummary(after: drawMarks(after: box.maxX + 6 + label.size().width))
