        switch character.lowercased() {
        case " ":
            playPause(nil)
        case "j":
            shuttle(forward: false)
        case "k":
            playback.pause()
        case "l":
            shuttle(forward: true)
        case "i":
            setInPoint(nil)
        case "o":
            setOutPoint(nil)
        case "n":
            toggleSnapping(nil)
        case "m":
            addMarker(nil)
        case "w":
            trimStartToPlayhead(nil)
        case "e":
            trimEndToPlayhead(nil)
        case "t":
            addTextClip(nil)
        case "c":
            toggleCropMode(nil)
